        uint256 afterBal = IERC20(usdc).balanceOf(attacker);
        emit log_named_uint("attackerAfter", afterBal);
        emit log_named_int("profitDelta", int256(afterBal) - int256(beforeBal));
        assertGt(afterBal, beforeBal);
